result=[]
for e,extra in zip(data,items):
 tools,materials,principle,procedure,observations,extraqa=extra
 blocks=[]
 def section(name,text=None):
  blocks.append({'type':'heading','text':name})
  if text:blocks.append({'type':'text','text':text})
 section('Aim',e['aim'])
 section('Tools Required',tools+'.')
 section('Materials Required',materials+'.')
 section('Working Principle',principle)
 section('Diagram')
 fig={'type':'figure','src':e['src'],'label':e['title']+' — conceptual diagram','width':660,'height':430}
 blocks.append(fig)
 section('Sequence of Operation')
 for i,step in enumerate(procedure.split('|'),1):blocks.append({'type':'text','text':str(i)+'. '+step})
 section('Observation and Inference')
 blocks.append({'type':'table','rows':[['Aspect','Conceptual interpretation']]+[list(x) for x in observations]})
 blocks.append({'type':'text','text':'These are explanatory relationships, not measured observations or claims that the physical experiment was performed.'})
 section('Questions and Answers')
 section('Pre Lab Questions')
 for i,q in enumerate(e['qa'],1):
  blocks.extend([{'type':'question','text':f'{i}. {q["q"]}'},{'type':'answer','text':'Answer: '+q['a']}])
 section('Post Lab Questions')
 for i,(q,a) in enumerate(extraqa,1):blocks.extend([{'type':'question','text':f'{i}. {q}'},{'type':'answer','text':'Answer: '+a}])
 section('Results','Expected learning outcome: '+e['aim']+' This describes the purpose of the exercise and does not certify a completed practical result.')
 result.append({'id':e['id'],'group':e['group'],'level':e['level'],'title':e['title'],'available':True,'blocks':blocks,'diagrams':[fig],'source':None})
(D/'content.json').write_text(json.dumps(result,ensure_ascii=False,indent=2))
